import{expect,test,beforeAll,beforeEach,afterEach,afterAll}from'vitest'
const errorView=e=>({name:e?.name??null,message:e?.message??String(e)})
const emit=row=>console.log('EXPECT_STATE_ROW '+JSON.stringify(row))
function state(phase){try{const value=expect.getState(),descriptor=Object.getOwnPropertyDescriptor(value,'environment');emit({kind:'state',phase,environment:typeof value.environment==='undefined'?'<undefined>':value.environment,own:!!descriptor,data:!!descriptor&&Object.hasOwn(descriptor,'value'),currentTestName:value.currentTestName??null})}catch(error){emit({kind:'state',phase,error:errorView(error)})}}
function shape(value){const properties={};for(const key of ['then','catch','finally'])try{properties[key]={type:typeof value[key]}}catch(error){properties[key]={error:errorView(error)}}return{type:typeof value,promise:value instanceof Promise,properties}}
state('collection')
beforeAll(()=>state('beforeAll'))
beforeEach(()=>state('beforeEach'))
test('actual expect state and polling',async()=>{state('body-before');let callbacks=0;let signal;const initial=expect.poll(options=>{callbacks++;signal={aborted:options.signal.aborted,instance:options.signal instanceof AbortSignal};return 1},{interval:1,timeout:1000});emit({kind:'poll-initial',shape:shape(initial),callbacks});const matched=initial.toBe(1);emit({kind:'poll-match',shape:shape(matched)});await matched;emit({kind:'poll-settled',callbacks,signal});state('body-after')})
afterEach(()=>state('afterEach'))
afterAll(()=>state('afterAll'))
